<?php
require_once __DIR__.'/../../config.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/protocolos.php';protocoloExigirAcesso();
if(getCargo()!=='ADMIN'){setMensagem('error','Somente o administrador gerencia unidades e catálogo.');redirecionar(APP_URL.'protocolos');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verificarCSRF($_POST['csrf_token']??'')){setMensagem('error','Sessão expirada.');redirecionar(APP_URL.'protocolos/configuracoes');}
 try{$a=trim($_POST['action']??'');
  if($a==='unidade'){$id=trim($_POST['id']??'')?:gerarUUID();$tipo=trim($_POST['tipo']??'');if(!in_array($tipo,['CAPITANIA','DELEGACIA','AGENCIA'],true))throw new RuntimeException('Tipo inválido.');$nome=trim($_POST['nome']??'');$cidade=trim($_POST['cidade']??'');$uf=strtoupper(trim($_POST['uf']??''));if(!$nome||!$cidade||!preg_match('/^[A-Z]{2}$/',$uf))throw new RuntimeException('Informe nome, cidade e UF.');$regex=trim($_POST['formato_protocolo_regex']??'')?:null;if($regex&&@preg_match($regex,'')===false)throw new RuntimeException('Expressão de validação inválida.');$q=$pdo->prepare("INSERT INTO protocolo_unidades_maritimas(id,codigo,nome,tipo,cidade,uf,endereco,telefone,email,jurisdicao,formato_protocolo_regex,url_consulta,ativo,criado_por)VALUES(:id,:codigo,:nome,:tipo,:cidade,:uf,:endereco,:telefone,:email,:jurisdicao,:regex,:url,1,:usuario) ON DUPLICATE KEY UPDATE codigo=VALUES(codigo),nome=VALUES(nome),tipo=VALUES(tipo),cidade=VALUES(cidade),uf=VALUES(uf),endereco=VALUES(endereco),telefone=VALUES(telefone),email=VALUES(email),jurisdicao=VALUES(jurisdicao),formato_protocolo_regex=VALUES(formato_protocolo_regex),url_consulta=VALUES(url_consulta),ativo=1");$q->execute([':id'=>$id,':codigo'=>trim($_POST['codigo']??'')?:null,':nome'=>$nome,':tipo'=>$tipo,':cidade'=>$cidade,':uf'=>$uf,':endereco'=>trim($_POST['endereco']??'')?:null,':telefone'=>trim($_POST['telefone']??'')?:null,':email'=>trim($_POST['email']??'')?:null,':jurisdicao'=>trim($_POST['jurisdicao']??'')?:null,':regex'=>$regex,':url'=>trim($_POST['url_consulta']??'')?:null,':usuario'=>$_SESSION['usuario_id']]);}
  elseif($a==='catalogo'){$codigo=strtoupper(trim($_POST['codigo']??''));$nome=trim($_POST['nome']??'');$cat=trim($_POST['categoria']??'OUTROS');$cats=['ANALISE_PLANOS','VISTORIA','INSCRICAO','CERTIFICADOS','PROPRIEDADE','RESPONSABILIDADE_TECNICA','DOCUMENTOS_PESSOAIS','OUTROS'];if(!$codigo||!preg_match('/^[A-Z0-9_]+$/',$codigo)||!$nome||!in_array($cat,$cats,true))throw new RuntimeException('Informe código estável, categoria e nome.');$q=$pdo->prepare('INSERT INTO protocolo_catalogo_documentos(id,codigo,categoria,nome,contexto,norma_referencia,ativo,ordem)VALUES(UUID(),:codigo,:cat,:nome,:contexto,:norma,1,:ordem) ON DUPLICATE KEY UPDATE categoria=VALUES(categoria),nome=VALUES(nome),contexto=VALUES(contexto),norma_referencia=VALUES(norma_referencia),ativo=1,ordem=VALUES(ordem)');$q->execute([':codigo'=>$codigo,':cat'=>$cat,':nome'=>$nome,':contexto'=>trim($_POST['contexto']??'')?:null,':norma'=>trim($_POST['norma_referencia']??'')?:null,':ordem'=>(int)($_POST['ordem']??0)]);}
  elseif($a==='alertas'){$q=$pdo->prepare('UPDATE protocolo_configuracoes SET valor=:valor,atualizado_por=:usuario WHERE chave=:chave');foreach(['dias_sem_comprovante','dias_sem_protocolo_oficial','dias_alerta_validade'] as $chave){$valor=max(1,min(365,(int)($_POST[$chave]??0)));$q->execute([':valor'=>(string)$valor,':usuario'=>$_SESSION['usuario_id'],':chave'=>$chave]);}}
  else throw new RuntimeException('Ação inválida.');
  setMensagem('success','Cadastro atualizado.');
 }catch(Throwable $e){setMensagem('error',$e->getMessage());}
 redirecionar(APP_URL.'protocolos/configuracoes');
}
$unidades=$pdo->query('SELECT * FROM protocolo_unidades_maritimas ORDER BY ativo DESC,tipo,nome')->fetchAll(PDO::FETCH_ASSOC);$docs=$pdo->query('SELECT * FROM protocolo_catalogo_documentos ORDER BY categoria,ordem,nome')->fetchAll(PDO::FETCH_ASSOC);try{$alertas=$pdo->query('SELECT chave,valor FROM protocolo_configuracoes')->fetchAll(PDO::FETCH_KEY_PAIR);}catch(Throwable $e){$alertas=[];}
