?><main class="conteudo-principal"><div style="display:flex;justify-content:space-between;gap:12px"><div><h1>Cadastros de protocolo</h1><p>Unidades marítimas e catálogo sugerido de documentos.</p></div><a class="btn btn-secondary" href="<?= APP_URL ?>protocolos">Voltar</a></div>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><section class="card"><div class="card-body"><h2>Unidade marítima</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= h(gerarCSRF()) ?>"><input type="hidden" name="action" value="unidade"><div class="form-group"><label>Código</label><input class="form-control" name="codigo"></div><div class="form-group"><label>Nome *</label><input class="form-control" name="nome" required></div><div class="form-group"><label>Tipo *</label><select class="form-control" name="tipo"><option>CAPITANIA</option><option>DELEGACIA</option><option>AGENCIA</option></select></div><div style="display:grid;grid-template-columns:2fr 1fr;gap:8px"><input class="form-control" name="cidade" required placeholder="Cidade"><input class="form-control" name="uf" required maxlength="2" placeholder="UF"></div><input class="form-control" name="endereco" placeholder="Endereço"><input class="form-control" name="telefone" placeholder="Telefone"><input class="form-control" name="email" type="email" placeholder="E-mail"><textarea class="form-control" name="jurisdicao" placeholder="Jurisdição"></textarea><input class="form-control" name="formato_protocolo_regex" placeholder="Regex opcional, ex.: /^\\d+$/"><input class="form-control" name="url_consulta" type="url" placeholder="Link oficial de consulta"><button class="btn btn-primary" style="margin-top:10px">Salvar unidade</button></form><hr><?php foreach($unidades as $u): ?><p><strong><?= h($u['nome']) ?></strong><br><small><?= h($u['tipo'].' · '.$u['cidade'].'/'.$u['uf']) ?></small></p><?php endforeach; ?></div></section>
<section class="card"><div class="card-body"><h2>Alertas</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= h(gerarCSRF()) ?>"><input type="hidden" name="action" value="alertas"><label>Dias sem comprovante de entrega</label><input class="form-control" type="number" min="1" max="365" name="dias_sem_comprovante" value="<?= h($alertas['dias_sem_comprovante']??3) ?>"><label>Dias sem protocolo oficial após envio</label><input class="form-control" type="number" min="1" max="365" name="dias_sem_protocolo_oficial" value="<?= h($alertas['dias_sem_protocolo_oficial']??3) ?>"><label>Antecedência da validade</label><input class="form-control" type="number" min="1" max="365" name="dias_alerta_validade" value="<?= h($alertas['dias_alerta_validade']??15) ?>"><button class="btn btn-primary" style="margin-top:10px">Salvar alertas</button></form><hr><h2>Documento do catálogo</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= h(gerarCSRF()) ?>"><input type="hidden" name="action" value="catalogo"><input class="form-control" required name="codigo" placeholder="CÓDIGO_ESTÁVEL"><input class="form-control" required name="nome" placeholder="Nome do documento"><select class="form-control" name="categoria"><?php foreach(['ANALISE_PLANOS','VISTORIA','INSCRICAO','CERTIFICADOS','PROPRIEDADE','RESPONSABILIDADE_TECNICA','DOCUMENTOS_PESSOAIS','OUTROS'] as $c): ?><option><?= $c ?></option><?php endforeach; ?></select><input class="form-control" name="contexto" placeholder="Contexto/serviço"><input class="form-control" name="norma_referencia" value="NORMAM-202/DPC" placeholder="Referência normativa"><input class="form-control" type="number" name="ordem" value="0"><button class="btn btn-primary" style="margin-top:10px">Salvar documento</button></form><hr><div style="max-height:520px;overflow:auto"><?php foreach($docs as $doc): ?><p><strong><?= h($doc['nome']) ?></strong><br><small><?= h($doc['codigo'].' · '.$doc['categoria'].($doc['contexto']?' · '.$doc['contexto']:'')) ?></small></p><?php endforeach; ?></div></div></section></div></main><style>@media(max-width:800px){.conteudo-principal>div[style*="grid-template-columns"]{grid-template-columns:1fr!important}}</style><?php require __DIR__.'/../../includes/footer.php'; ?>
